// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAgents List agents as trees, by project name, then name
	// (GET /v1/agents)
	ListAgents(w http.ResponseWriter, r *http.Request, params ListAgentsParams)
	// CreateAgent Create an agent and start its AI coding agent
	// (POST /v1/agents)
	CreateAgent(w http.ResponseWriter, r *http.Request)
	// DeleteAgent Delete an agent
	// (DELETE /v1/agents/{agent})
	DeleteAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params DeleteAgentParams)
	// GetAgent An agent, in any state
	// (GET /v1/agents/{agent})
	GetAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params GetAgentParams)
	// UpdateAgent Rename an agent
	// (PATCH /v1/agents/{agent})
	UpdateAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params UpdateAgentParams)
	// GetAgentHistory Lines of an agent's history, in any state
	// (GET /v1/agents/{agent}/history)
	GetAgentHistory(w http.ResponseWriter, r *http.Request, agent AgentRef, params GetAgentHistoryParams)
	// SendAgent Queue a message for a running agent
	// (POST /v1/agents/{agent}/send)
	SendAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params SendAgentParams)
	// StartAgent Start an agent whose AI coding agent ended, in the same session
	// (POST /v1/agents/{agent}/start)
	StartAgent(w http.ResponseWriter, r *http.Request, agent AgentRef, params StartAgentParams)
	// GetDaemon The daemon serving this socket
	// (GET /v1/daemon)
	GetDaemon(w http.ResponseWriter, r *http.Request)
	// ReloadDaemon Read the settings again and apply them
	// (POST /v1/daemon/reload)
	ReloadDaemon(w http.ResponseWriter, r *http.Request)
	// ListProjects List projects, without their worktrees, sorted by name
	// (GET /v1/projects)
	ListProjects(w http.ResponseWriter, r *http.Request, params ListProjectsParams)
	// CreateProject Create a project or open a git repository as one
	// (POST /v1/projects)
	CreateProject(w http.ResponseWriter, r *http.Request)
	// DeleteProject Delete a project and everything that belongs to it
	// (DELETE /v1/projects/{project})
	DeleteProject(w http.ResponseWriter, r *http.Request, project ProjectRef, params DeleteProjectParams)
	// GetProject A project, open or closed, with which of its checkouts are on disk and its terminals and agents
	// (GET /v1/projects/{project})
	GetProject(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// UpdateProject Close a project, or open it again from one of its checkouts
	// (PATCH /v1/projects/{project})
	UpdateProject(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// StreamProject Follow a project, sent whole every time it changes
	// (GET /v1/projects/{project}/events)
	StreamProject(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// RecloneProject Clone a project with no checkout left back into its clone path
	// (POST /v1/projects/{project}/worktrees)
	RecloneProject(w http.ResponseWriter, r *http.Request, project ProjectRef)
	// ListTerminals List terminals by project name, then name
	// (GET /v1/terminals)
	ListTerminals(w http.ResponseWriter, r *http.Request, params ListTerminalsParams)
	// CreateTerminal Create a terminal and start its shell
	// (POST /v1/terminals)
	CreateTerminal(w http.ResponseWriter, r *http.Request)
	// DeleteTerminal Delete a terminal
	// (DELETE /v1/terminals/{terminal})
	DeleteTerminal(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params DeleteTerminalParams)
	// GetTerminal A terminal, in any state
	// (GET /v1/terminals/{terminal})
	GetTerminal(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params GetTerminalParams)
	// GetTerminalHistory Lines of a terminal's history, in any state
	// (GET /v1/terminals/{terminal}/history)
	GetTerminalHistory(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params GetTerminalHistoryParams)
	// SendTerminal Queue a message for a running terminal's shell
	// (POST /v1/terminals/{terminal}/send)
	SendTerminal(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params SendTerminalParams)
	// StartTerminal Start a fresh shell for a terminal whose last one ended
	// (POST /v1/terminals/{terminal}/start)
	StartTerminal(w http.ResponseWriter, r *http.Request, terminal TerminalRef, params StartTerminalParams)
	// GetVersion Version of the daemon
	// (GET /v1/version)
	GetVersion(w http.ResponseWriter, r *http.Request)
}

