// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAgents List agents as trees, by project name, then name
	// (GET /v1/agents)
	ListAgents(ctx context.Context, request ListAgentsRequestObject) (ListAgentsResponseObject, error)
	// CreateAgent Create an agent and start its AI coding agent
	// (POST /v1/agents)
	CreateAgent(ctx context.Context, request CreateAgentRequestObject) (CreateAgentResponseObject, error)
	// DeleteAgent Delete an agent
	// (DELETE /v1/agents/{agent})
	DeleteAgent(ctx context.Context, request DeleteAgentRequestObject) (DeleteAgentResponseObject, error)
	// GetAgent An agent, in any state
	// (GET /v1/agents/{agent})
	GetAgent(ctx context.Context, request GetAgentRequestObject) (GetAgentResponseObject, error)
	// UpdateAgent Rename an agent
	// (PATCH /v1/agents/{agent})
	UpdateAgent(ctx context.Context, request UpdateAgentRequestObject) (UpdateAgentResponseObject, error)
	// GetAgentHistory Lines of an agent's history, in any state
	// (GET /v1/agents/{agent}/history)
	GetAgentHistory(ctx context.Context, request GetAgentHistoryRequestObject) (GetAgentHistoryResponseObject, error)
	// SendAgent Queue a message for a running agent
	// (POST /v1/agents/{agent}/send)
	SendAgent(ctx context.Context, request SendAgentRequestObject) (SendAgentResponseObject, error)
	// StartAgent Start an agent whose AI coding agent ended, in the same session
	// (POST /v1/agents/{agent}/start)
	StartAgent(ctx context.Context, request StartAgentRequestObject) (StartAgentResponseObject, error)
	// GetDaemon The daemon serving this socket
	// (GET /v1/daemon)
	GetDaemon(ctx context.Context, request GetDaemonRequestObject) (GetDaemonResponseObject, error)
	// ReloadDaemon Read the settings again and apply them
	// (POST /v1/daemon/reload)
	ReloadDaemon(ctx context.Context, request ReloadDaemonRequestObject) (ReloadDaemonResponseObject, error)
	// ListProjects List projects, without their worktrees, sorted by name
	// (GET /v1/projects)
	ListProjects(ctx context.Context, request ListProjectsRequestObject) (ListProjectsResponseObject, error)
	// CreateProject Create a project or open a git repository as one
	// (POST /v1/projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)
	// DeleteProject Delete a project and everything that belongs to it
	// (DELETE /v1/projects/{project})
	DeleteProject(ctx context.Context, request DeleteProjectRequestObject) (DeleteProjectResponseObject, error)
	// GetProject A project, open or closed, with which of its checkouts are on disk and its terminals and agents
	// (GET /v1/projects/{project})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)
	// UpdateProject Close a project, or open it again from one of its checkouts
	// (PATCH /v1/projects/{project})
	UpdateProject(ctx context.Context, request UpdateProjectRequestObject) (UpdateProjectResponseObject, error)
	// StreamProject Follow a project, sent whole every time it changes
	// (GET /v1/projects/{project}/events)
	StreamProject(ctx context.Context, request StreamProjectRequestObject) (StreamProjectResponseObject, error)
	// RecloneProject Clone a project with no checkout left back into its clone path
	// (POST /v1/projects/{project}/worktrees)
	RecloneProject(ctx context.Context, request RecloneProjectRequestObject) (RecloneProjectResponseObject, error)
	// ListTerminals List terminals by project name, then name
	// (GET /v1/terminals)
	ListTerminals(ctx context.Context, request ListTerminalsRequestObject) (ListTerminalsResponseObject, error)
	// CreateTerminal Create a terminal and start its shell
	// (POST /v1/terminals)
	CreateTerminal(ctx context.Context, request CreateTerminalRequestObject) (CreateTerminalResponseObject, error)
	// DeleteTerminal Delete a terminal
	// (DELETE /v1/terminals/{terminal})
	DeleteTerminal(ctx context.Context, request DeleteTerminalRequestObject) (DeleteTerminalResponseObject, error)
	// GetTerminal A terminal, in any state
	// (GET /v1/terminals/{terminal})
	GetTerminal(ctx context.Context, request GetTerminalRequestObject) (GetTerminalResponseObject, error)
	// GetTerminalHistory Lines of a terminal's history, in any state
	// (GET /v1/terminals/{terminal}/history)
	GetTerminalHistory(ctx context.Context, request GetTerminalHistoryRequestObject) (GetTerminalHistoryResponseObject, error)
	// SendTerminal Queue a message for a running terminal's shell
	// (POST /v1/terminals/{terminal}/send)
	SendTerminal(ctx context.Context, request SendTerminalRequestObject) (SendTerminalResponseObject, error)
	// StartTerminal Start a fresh shell for a terminal whose last one ended
	// (POST /v1/terminals/{terminal}/start)
	StartTerminal(ctx context.Context, request StartTerminalRequestObject) (StartTerminalResponseObject, error)
	// GetVersion Version of the daemon
	// (GET /v1/version)
	GetVersion(ctx context.Context, request GetVersionRequestObject) (GetVersionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

